import heapq

class MaxStack:
    def __init__(self):
        self.stack = []      # (value, id) in stack order
        self.heap = []       # (-value, -id): max value first, top-most (largest id) on ties
        self.removed = set() # ids already removed by pop or popMax
        self.cnt = 0         # id generator

    def push(self, x: int) -> None:
        self.cnt += 1
        self.stack.append((x, self.cnt))
        heapq.heappush(self.heap, (-x, -self.cnt))

    def _clean_stack(self) -> None:
        while self.stack and self.stack[-1][1] in self.removed:
            self.stack.pop()

    def _clean_heap(self) -> None:
        while self.heap and -self.heap[0][1] in self.removed:
            heapq.heappop(self.heap)

    def pop(self) -> int:
        self._clean_stack()
        x, i = self.stack.pop()
        self.removed.add(i)
        return x

    def top(self) -> int:
        self._clean_stack()
        return self.stack[-1][0]

    def peekMax(self) -> int:
        self._clean_heap()
        return -self.heap[0][0]

    def popMax(self) -> int:
        self._clean_heap()
        neg_x, neg_i = heapq.heappop(self.heap)
        self.removed.add(-neg_i)
        return -neg_x
